), ins as (
  insert into public.vocabulary_bank (word_key, word_ko, word_rom, word_en, level, is_active, frequency, pos, example_ko, source, qa_at)
  select v.ko, v.ko, v.rom, v.en, v.level, true, 0, v.pos, v.example_ko, 'krdict', now() from v
